#include <stdio.h>

static int values[100000], deque[100000];

int main(void) {
    int n, k;
    if (scanf("%d %d", &n, &k) != 2 || k < 1 || n < k || n > 100000) {
        return 0;
    }
    for (int i = 0; i < n; i++) {
        scanf("%d", &values[i]);
    }
    int head = 0, size = 0;
    for (int i = 0; i < n; i++) {
        if (size > 0 && deque[head] <= i - k) {
            head = (head + 1) % k;
            size--;
        }
        while (size > 0 && values[deque[(head + size - 1) % k]] <= values[i]) {
            size--;
        }
        deque[(head + size) % k] = i;
        size++;
        if (i >= k - 1) {
            printf(i + 1 < n ? "%d " : "%d\n", values[deque[head]]);
        }
    }
    return 0;
}

